export const WASMOS_ERR_THREAD_NOT_OWNER: i32 = -0x00150005; // the thread belongs to another process
export const WASMOS_ERR_THREAD_BUSY: i32 = -0x00150006; // another thread is already joining it
export const WASMOS_ERR_ENV_NOT_FOUND: i32 = -0x00160001; // no entry with that key
export const WASMOS_ERR_ENV_TOO_LONG: i32 = -0x00160002; // the key or value exceeds the store's fixed capacity
export const WASMOS_ERR_ENV_TABLE_FULL: i32 = -0x00160003; // no free entry remains
export const WASMOS_ERR_FRAMEBUFFER_NOT_PRESENT: i32 = -0x00170001; // no framebuffer is available on this system
export const WASMOS_ERR_FRAMEBUFFER_TOO_SMALL: i32 = -0x00170002; // the caller's requested mapping is smaller than the framebuffer
export const WASMOS_ERR_DEVMGR_NO_MOUNT_RULE: i32 = -0x000A0001; // no block/filesystem mount rule matches the requested unit
export const WASMOS_ERR_DEVMGR_UNSUPPORTED_QUERY: i32 = -0x000A0002; // unknown or unsupported device-manager query type
export const WASMOS_ERR_VIRTIO_BLK_NOT_READY: i32 = -0x00180001; // no virtio-blk device was probed, or bring-up did not complete
export const WASMOS_ERR_VIRTIO_BLK_BAD_REQUEST: i32 = -0x00180002; // the request's lba, sector count, or buffer argument is unusable
export const WASMOS_ERR_VIRTIO_BLK_UNSUPPORTED_REQUEST: i32 = -0x00180003; // unknown or unsupported block opcode
export const WASMOS_ERR_VIRTIO_BLK_QUEUE_FULL: i32 = -0x00180004; // no descriptors are free; the request must be retried
export const WASMOS_ERR_VIRTIO_BLK_IO_ERROR: i32 = -0x00180005; // the device completed the request with a non-OK virtio-blk status
export const WASMOS_ERR_VIRTIO_BLK_TIMEOUT: i32 = -0x00180006; // the device never reported the request on the used ring
export const WASMOS_ERR_VIRTIO_BLK_READ_ONLY: i32 = -0x00180007; // the device negotiated VIRTIO_BLK_F_RO and cannot be written

export function errMake(dom: u16, code: u16): i32 {
  return -(<i32>(((<u32>dom) << 16) | (<u32>code)));
}
export function errDomainOf(x: i32): u16 { return <u16>((<u32>(-x)) >> 16); }
export function errCodeOf(x: i32): u16 { return <u16>((<u32>(-x)) & 0xffff); }

export function statusStr(s: i32): string {
  switch (s) {
    case WASMOS_OK: return "OK";
    case WASMOS_INVAL: return "INVAL";
    case WASMOS_DENIED: return "DENIED";
    case WASMOS_FULL: return "FULL";
    case WASMOS_NOENT: return "NOENT";
    case WASMOS_TIMEOUT: return "TIMEOUT";
    case WASMOS_NOMEM: return "NOMEM";
    case WASMOS_UNSUPPORTED: return "UNSUPPORTED";
    case WASMOS_PEER_GONE: return "PEER_GONE";
    case WASMOS_AGAIN: return "AGAIN";
    default: return "UNKNOWN_STATUS";
  }
}

export function errorDomainName(d: u16): string {
  switch (d) {
    case WASMOS_ERR_DOMAIN_NONE: return "none";
    case WASMOS_ERR_DOMAIN_PROC_SPAWN: return "proc_spawn";
    case WASMOS_ERR_DOMAIN_PROC_PM: return "proc_pm";
    case WASMOS_ERR_DOMAIN_SHMEM: return "shmem";
    case WASMOS_ERR_DOMAIN_FS: return "fs";
    case WASMOS_ERR_DOMAIN_NET: return "net";
    case WASMOS_ERR_DOMAIN_GFX: return "gfx";
    case WASMOS_ERR_DOMAIN_DRIVER: return "driver";
    case WASMOS_ERR_DOMAIN_VT: return "vt";
    case WASMOS_ERR_DOMAIN_CHARDEV: return "chardev";
    case WASMOS_ERR_DOMAIN_HRNG: return "hrng";
    case WASMOS_ERR_DOMAIN_DMA: return "dma";
    case WASMOS_ERR_DOMAIN_IRQ: return "irq";
    case WASMOS_ERR_DOMAIN_MSI: return "msi";
    case WASMOS_ERR_DOMAIN_IO: return "io";
    case WASMOS_ERR_DOMAIN_FONT: return "font";
    case WASMOS_ERR_DOMAIN_RTC: return "rtc";
    case WASMOS_ERR_DOMAIN_XFER_BUFFER: return "xfer_buffer";
    case WASMOS_ERR_DOMAIN_KERNEL: return "kernel";
    case WASMOS_ERR_DOMAIN_BLOCK: return "block";
    case WASMOS_ERR_DOMAIN_THREAD: return "thread";
    case WASMOS_ERR_DOMAIN_ENV: return "env";
    case WASMOS_ERR_DOMAIN_FRAMEBUFFER: return "framebuffer";
    case WASMOS_ERR_DOMAIN_DEVMGR: return "devmgr";
    case WASMOS_ERR_DOMAIN_VIRTIO_BLK: return "virtio_blk";
    default: return "unknown";
  }
}

